CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,full_name TEXT NOT NULL,username TEXT UNIQUE NOT NULL,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,phone TEXT,role TEXT NOT NULL DEFAULT 'customer',status TEXT DEFAULT 'Active',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER UNIQUE,full_name TEXT,email TEXT,phone TEXT,address TEXT,city TEXT,postal_code TEXT,latitude REAL,longitude REAL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS riders (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER UNIQUE,vehicle_type TEXT,vehicle_number TEXT,license_number TEXT,status TEXT DEFAULT 'Available',current_latitude REAL,current_longitude REAL,last_location_update TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY AUTOINCREMENT,tracking_number TEXT UNIQUE,customer_id INTEGER,rider_id INTEGER,pickup_address TEXT NOT NULL,pickup_latitude REAL,pickup_longitude REAL,delivery_address TEXT NOT NULL,delivery_latitude REAL,delivery_longitude REAL,package_description TEXT,package_weight REAL DEFAULT 0,package_quantity INTEGER DEFAULT 1,delivery_type TEXT DEFAULT 'Standard',delivery_fee REAL DEFAULT 0,total_amount REAL DEFAULT 0,payment_method TEXT DEFAULT 'Cash on Delivery',payment_status TEXT DEFAULT 'Pending',order_status TEXT DEFAULT 'Pending',special_instructions TEXT,scheduled_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_status_history (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER,status TEXT,changed_by INTEGER,notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS delivery_proofs (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER,rider_id INTEGER,proof_type TEXT,file_url TEXT,signature_data TEXT,otp TEXT,verified_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER,amount REAL,payment_method TEXT,payment_status TEXT,transaction_reference TEXT,paid_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,type TEXT,title TEXT,message TEXT,related_order_id INTEGER,is_read INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pricing_rules (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,base_fee REAL,per_km_fee REAL,per_kg_fee REAL,express_fee REAL,same_day_fee REAL,active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rider_locations (id INTEGER PRIMARY KEY AUTOINCREMENT,rider_id INTEGER,order_id INTEGER,latitude REAL,longitude REAL,recorded_at TEXT DEFAULT CURRENT_TIMESTAMP);
